using OffsetArrays

function chunks(v::AbstractVector, n::Integer)
    n >= 1 || throw(ArgumentError("chunk size must be at least 1, got $n"))
    return Iterators.partition(v, n)
end

# Checks
v = collect(1:7)
cs = collect(chunks(v, 3))
v[1] = 100

o = OffsetArray(collect(1:7), -3:3)
@assert collect(chunks(o, 3)) == [[1, 2, 3], [4, 5, 6], [7]]
@assert collect(chunks(Float32[], 4)) == Vector{Float32}[]
@assert collect(chunks(view(collect(1:10), 4:9), 4)) == [[4, 5, 6, 7], [8, 9]]

err = try chunks(v, 0); nothing catch e; e end
@assert err isa ArgumentError && occursin("at least 1", err.msg)
```

The standard library already does this: `Iterators.partition` takes the array's own indices into account, returns views for arrays, and reports its `length`. The only code worth writing is the argument check, so a bad size fails with a message that names the problem. A hand-rolled version with `1:n:length(v)` would have been wrong on the offset array, where the first index is `-3`.

```julia
struct SparseVec{T}
    n::Int
    nz::Dict{Int,T}
    function SparseVec{T}(n::Integer) where {T}
        n >= 0 || throw(ArgumentError("length must be non-negative, got $n"))
        return new{T}(n, Dict{Int,T}())
    end
end

Base.length(v::SparseVec) = v.n
Base.eltype(::Type{SparseVec{T}}) where {T} = T

function Base.getindex(v::SparseVec{T}, i::Integer) where {T}
    checkbounds(Bool, 1:v.n, i) || throw(BoundsError(v, i))
    return get(v.nz, i, zero(T))
end

function Base.setindex!(v::SparseVec{T}, x, i::Integer) where {T}
    checkbounds(Bool, 1:v.n, i) || throw(BoundsError(v, i))
    xt = convert(T, x)
    if iszero(xt)
        delete!(v.nz, i)
    else
        v.nz[i] = xt
    end
    return v
end

function dot(a::SparseVec{S}, b::SparseVec{T}) where {S,T}
    a.n == b.n || throw(DimensionMismatch("lengths differ: $(a.n) vs $(b.n)"))
    acc = zero(S) * zero(T)
    small, large = length(a.nz) <= length(b.nz) ? (a, b) : (b, a)
    for i in keys(small.nz)
        acc += get(a.nz, i, zero(S)) * get(b.nz, i, zero(T))
    end
    return acc
end

# Checks
a = SparseVec{Float32}(5); a[2] = 2; a[4] = 4
b = SparseVec{Float32}(5); b[4] = 0.5; b[5] = 7
@assert a[1] === 0.0f0 && a[2] === 2.0f0

r = SparseVec{Rational{Int}}(3); r[1] = 1//3; r[3] = 2
r[1] = 0
@assert length(r.nz) == 1                                 # assigning zero removes the entry

i3 = SparseVec{Int}(3); i3[1] = 2
@assert dot(i3, r) isa Rational{Int}

err = try dot(a, SparseVec{Float32}(4)); nothing catch e; e end
@assert err isa DimensionMismatch && occursin("lengths differ", err.msg)
```

The element type of every result comes from `zero(T)` and from products of zeros, so `Float32` stays `Float32`, `Rational` stays exact, and an empty or all-zero vector still returns a typed zero rather than `0.0`. Stored zeros are deleted on assignment, which keeps `nz` honest and keeps `dot` proportional to the number of stored entries. `eltype` is defined on the type, which is what `collect` and `similar` consult.

```julia
function primes_upto(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative, got $n"))
    N = Int(n)                                      # all arithmetic in Int: i*i overflows Int8
    N < 2 && return typeof(n)[]
    composite = falses(N)
    for i in 2:isqrt(N)
        composite[i] && continue
        for m in i*i:i:N
            composite[m] = true
        end
    end
    return typeof(n)[i for i in 2:N if !composite[i]]
end

# Checks
@assert primes_upto(1) == Int[] && primes_upto(0) == Int[]
@assert length(primes_upto(Int8(127))) == 31 && last(primes_upto(Int8(127))) == Int8(127)
@assert primes_upto(UInt16(65535)) isa Vector{UInt16}

err = try primes_upto(-1); nothing catch e; e end
@assert err isa ArgumentError && occursin("non-negative", err.msg)
```

The result element type is `typeof(n)`, so callers that pass `Int8` or `UInt16` get a vector of that type, including the empty case (`typeof(n)[]`, not `Int[]`). The sieve itself runs in `Int`: with `Int8` the product `12 * 12` would wrap, so the marking loop converts once at the top. A `BitVector` stores one bit per number.

```julia
struct Polynomial{T<:Number}
    coeffs::Vector{T}                       # ascending powers, no trailing zeros
    function Polynomial{T}(coeffs) where {T<:Number}
        c = Vector{T}(coeffs)               # converts and copies, so the caller's array is not aliased
        while !isempty(c) && iszero(last(c))
            pop!(c)
        end
        return new{T}(c)
    end
end
Polynomial(coeffs::AbstractVector{T}) where {T<:Number} = Polynomial{T}(coeffs)

function (p::Polynomial)(x)
    c = p.coeffs
    isempty(c) && return zero(x) * zero(eltype(c))
    acc = c[end] * one(x)
    for i in lastindex(c)-1:-1:firstindex(c)
        acc = acc * x + c[i]
    end
    return acc
end

function Base.:+(a::Polynomial{S}, b::Polynomial{T}) where {S,T}
    R = promote_type(S, T)
    c = zeros(R, max(length(a.coeffs), length(b.coeffs)))
    for (i, x) in enumerate(a.coeffs); c[i] += x; end
    for (i, x) in enumerate(b.coeffs); c[i] += x; end
    return Polynomial{R}(c)
end

function Base.:*(a::Polynomial{S}, b::Polynomial{T}) where {S,T}
    R = promote_type(S, T)
    (isempty(a.coeffs) || isempty(b.coeffs)) && return Polynomial{R}(R[])
    c = zeros(R, length(a.coeffs) + length(b.coeffs) - 1)
    for (j, y) in enumerate(b.coeffs), (i, x) in enumerate(a.coeffs)
        c[i+j-1] += x * y
    end
    return Polynomial{R}(c)
end

Base.:(==)(a::Polynomial, b::Polynomial) = a.coeffs == b.coeffs

# Checks
p = Polynomial([1, 2, 3])
@assert p isa Polynomial{Int} && p(2) === 17

v = [1, 2]; q = Polynomial(v); v[1] = 99

s = Polynomial([1, 2]) + Polynomial([0.5, 0.0, 4.0])
@assert s isa Polynomial{Float64} && s.coeffs == [1.5, 2.0, 4.0]
r = Polynomial([1//1, 1//1])
@assert (r * r) == Polynomial([1//1, 2//1, 1//1]) && (r * r) isa Polynomial{Rational{Int}}

@assert (try Polynomial{Int}([1.5]); false catch e; e isa InexactError end)
```

The inner constructor takes an unconstrained argument and lets `Vector{T}(coeffs)` do the conversion, so `Polynomial{Float64}([1, 2])` works; a lossy request such as `Polynomial{Int}([1.5])` raises `InexactError` instead of truncating. The outer constructor only computes `T` from the vector and delegates inward. `zeros(R, n)` and `zero(x) * zero(eltype(c))` follow the element type, so nothing is forced to `Float64`, and the empty polynomial evaluates to a typed zero.

```julia
function letter_counts(s::AbstractString)
    counts = Dict{Char,Int}()
    for c in s
        isletter(c) || continue
        c = lowercase(c)
        counts[c] = get(counts, c, 0) + 1
    end
    return sort!(collect(counts); by = p -> (-last(p), first(p)))
end

# Checks
r = letter_counts("Ñandú ñu")
@assert r isa Vector{Pair{Char,Int}}
@assert letter_counts("123 !?") == Pair{Char,Int}[]
@assert letter_counts("Straße") == ['a' => 1, 'e' => 1, 'r' => 1, 's' => 1, 't' => 1, 'ß' => 1]
@assert letter_counts("b a") == letter_counts("a b")        # deterministic regardless of dict order
```

`for c in s` iterates characters, `isletter` and `lowercase` are Unicode-aware, and the key is a `Char`, so `ñ` and `n` are different letters while `Ñ` and `ñ` are the same. `Dict` iteration order is unspecified, so the result is sorted with a total order on `(-count, char)`; without the second key ties would come out in arbitrary order and tests would be flaky. `lowercase('ß')` is `'ß'` (no single-character expansion), so it is counted as itself.

```julia
using OffsetArrays

function report(name::AbstractString, v::AbstractVector)
    io = IOBuffer()
    for i in eachindex(v)
        println(io, "$(name)[$i] = $(v[i])")
    end
    return String(take!(io))
end

# Checks
@assert report("x", [1.5, 2.5]) == "x[1] = 1.5\nx[2] = 2.5\n"
@assert report("ñ", ["é", "日本"]) == "ñ[1] = é\nñ[2] = 日本\n"
@assert report("o", OffsetArray([10, 20], 4:5)) == "o[4] = 10\no[5] = 20\n"
@assert report("w", view([1, 2, 3, 4], 2:3)) == "w[1] = 2\nw[2] = 3\n"
```

Two defects. In `"$name[$i] = $v[i]"`, interpolation takes the identifier `v` alone, so each line printed the entire vector followed by the literal text `[i]`; an element access must be wrapped as `$(v[i])`. The name is wrapped too (`$(name)[...]`) so the following `[` can never be read as indexing. Second, `1:length(v)` assumes 1-based indices: with an `OffsetArray` it indexes out of range or labels the wrong elements, while `eachindex(v)` yields whatever valid indices the array has. Returning a `String` rather than printing makes the function testable; callers can `print(report(...))`.
